15	import java.math.BigDecimal;
16	import java.time.LocalDate;
17	import java.time.YearMonth;
18	import java.util.ArrayList;
19	import java.util.List;
20	
21	/** A person's plan: a DRAFT claim of its amount for each plan date, up to its end. The plan dates
22	 *  are its start and then every so many days; or, for a monthly plan, its day of the month in every
23	 *  month from the start's month (a day beyond the month's length falling on its last day), leaving
24	 *  out those before the start. A date on or after the day the plan was paused and before the day it
25	 *  was resumed is skipped, not postponed; while it is paused, every date from the day it was. */
26	@Entity
27	@Table(name = "plan")
28	public class Plan {
29	
30	    @Id
31	    @GeneratedValue(strategy = GenerationType.IDENTITY)
32	    private Long id;
33	
34	    @Column(name = "sheet_id", nullable = false)
35	    private String sheetId;
36	
37	    @Column(name = "person_id", nullable = false)
38	    private long personId;
39	
40	    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
41	    private BigDecimal amount;
42	
43	    @Column(name = "start_date", nullable = false)
44	    private LocalDate start;
45	
46	    @Column(name = "every_days")
47	    private Integer every;
48	
49	    @Column(name = "month_day")
50	    private Integer day;
51	
52	    @Column(name = "end_date", nullable = false)
53	    private LocalDate end;
54	
55	    /** The sheet's today the plan was paused on; null while it runs. */
56	    @Column(name = "paused_on")
57	    private LocalDate pausedOn;
58	
59	    /** The plan's past pauses, in the order they were resumed. */
60	    @ElementCollection(fetch = FetchType.EAGER)
61	    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
62	    @OrderColumn(name = "position")
63	    private List<Pause> pauses = new ArrayList<>();
64	
65	    /** A past pause: from the day the plan was paused (inclusive) to the day it was resumed (exclusive). */
66	    @Embeddable
67	    public record Pause(@Column(name = "from_date", nullable = false) LocalDate from,
68	            @Column(name = "to_date", nullable = false) LocalDate to) {
69	        /** Whether a plan date falls within it: on or after the from and before the to. */
70	        public boolean covers(LocalDate date) {
71	            return !date.isBefore(from) && date.isBefore(to);
72	        }
73	    }
74	
75	    protected Plan() {
76	    }
77	
78	    /** A plan of either an interval in days or a day of the month; the other is null. */
79	    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
80	            LocalDate end) {
81	        this.sheetId = sheetId;
82	        this.personId = personId;
83	        this.amount = amount;
84	        this.start = start;
85	        this.every = every;
86	        this.day = day;
87	        this.end = end;
88	    }
89	
90	    public Long getId() {
91	        return id;
92	    }
93	
94	    public String getSheetId() {
95	        return sheetId;
96	    }
97	
98	    public long getPersonId() {
99	        return personId;
100	    }
101	
102	    public BigDecimal getAmount() {
103	        return amount;
104	    }
105	
106	    public LocalDate getStart() {
107	        return start;
108	    }
109	
110	    /** The interval in days; null for a monthly plan. */
111	    public Integer getEvery() {
112	        return every;
113	    }
114	
115	    /** The day of the month of a monthly plan; null for a plan of an interval in days. */
116	    public Integer getDay() {
117	        return day;
118	    }
119	
120	    public LocalDate getEnd() {
121	        return end;
122	    }
123	
124	    public boolean isPaused() {
125	        return pausedOn != null;
126	    }
127	
128	    /** The sheet's today the plan was paused on; null while it runs. */
129	    public LocalDate getPausedOn() {
130	        return pausedOn;
131	    }
132	
133	    public List<Pause> getPauses() {
134	        return List.copyOf(pauses);
135	    }
136	
137	    /** Pause the plan on a day: its dates from that day on are skipped until it is resumed. */
138	    public void pause(LocalDate on) {
139	        pausedOn = on;
140	    }
141	
142	    /** Resume the plan on a day: its pause is kept as a past one, to that day. */
143	    public void resume(LocalDate on) {
144	        pauses.add(new Pause(pausedOn, on));
145	        pausedOn = null;
146	    }
147	
148	    /** Whether the plan skips a date: one of its pauses covers it. */
149	    public boolean skips(LocalDate date) {
150	        return (pausedOn != null && !date.isBefore(pausedOn)) || pauses.stream().anyMatch(p -> p.covers(date));
151	    }
152	
